if ($_SERVER['REQUEST_METHOD'] !== 'POST') { http_response_code(405); echo json_encode(['error'=>'POST required']); exit; }
$body=json_decode(file_get_contents('php://input'),true)?:[]; $thLevel=(int)($body['townHall']??0);
