function bmax($th,$b){$m=['Barrack'=>'maxBarracks','Dark Barrack'=>'maxDarkBarracks','Spell Factory'=>'maxSpellFactory','Dark Spell Factory'=>'maxDarkSpellFactory','Workshop'=>'maxWorkshop'];$k=$m[$b]??null;return $k?($th[$k]??null):null;}
function avail($items,$th){$o=[];foreach($items as $u){$best=null;foreach(($u['levels']??[]) as $l){$b=bmax($th,$u['productionBuilding']??'');$okb=$b===null||((int)($l['buildingLevel']??0)<=(int)$b);$okl=(int)($l['laboratoryLevel']??0)<=(int)($th['maxLaboratory']??0);if($okb&&$okl)$best=$l;}if($best)$o[]=['name'=>$u['name'],'housingSpace'=>(int)($u['housingSpace']??0),'maxLevel'=>(int)($best['level']??1),'isSuper'=>(bool)($u['isSuper']??false)];}return $o;}
