$allowed=['townHall'=>$thLevel,'capacity'=>['troops'=>(int)$th['troopCapacity'],'spells'=>(int)$th['spellCapacity'],'siege'=>(int)$th['siegeCapacity'],'ccTroops'=>(int)$th['ccTroopCapacity'],'ccSpells'=>(int)$th['ccSpellCapacity'],'ccSiege'=>(int)$th['ccSiegeCapacity']],'troops'=>avail($data['troops'],$th),'spells'=>avail($data['spells'],$th),'sieges'=>array_map(fn($s)=>['name'=>$s['name']],array_filter($data['sieges'],fn($s)=>(int)$th['siegeCapacity']>0)),'heroes'=>$th['heroMaxLevels'],'pets'=>simple($data['pets'],$th,'pet'),'equipment'=>simple($data['equipment'],$th,'equipment')];
