$r=json_decode($res,true);$content=$r['choices'][0]['message']['content']??null;$army=json_decode($content,true);if(!$army){http_response_code(502);echo json_encode(['error'=>'AI returned invalid JSON']);exit;}
$tm=[];foreach($allowed['troops'] as $x)$tm[$x['name']]=$x['housingSpace'];$sm=[];foreach($allowed['spells'] as $x)$sm[$x['name']]=$x['housingSpace'];$tu=0;$su=0;foreach(($army['troops']??[]) as $x){$n=$x['name']??'';$q=(int)($x['quantity']??0);if(!isset($tm[$n])||$q<0){http_response_code(422);echo json_encode(['error'=>'Invalid troop','unit'=>$n]);exit;}$tu+=$tm[$n]*$q;}foreach(($army['spells']??[]) as $x){$n=$x['name']??'';$q=(int)($x['quantity']??0);if(!isset($sm[$n])||$q<0){http_response_code(422);echo json_encode(['error'=>'Invalid spell','unit'=>$n]);exit;}$su+=$sm[$n]*$q;}if($tu>$allowed['capacity']['troops']||$su>$allowed['capacity']['spells']){http_response_code(422);echo json_encode(['error'=>'Army exceeds capacity','troopUsed'=>$tu,'troopCapacity'=>$allowed['capacity']['troops'],'spellUsed'=>$su,'spellCapacity'=>$allowed['capacity']['spells']]);exit;}$army['usage']=['troops'=>$tu,'troopCapacity'=>$allowed['capacity']['troops'],'spells'=>$su,'spellCapacity'=>$allowed['capacity']['spells']];echo json_encode($army,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
